import type { SeatHistoryCompletion } from "./seat-history-stream";
import type {
  BrowserViewport,
  RyeOsEffectResult,
  RyeOsEnvelope,
  RyeOsEvent,
  RyeOsKeyEvent,
  RyeOsUiEvent,
  SeatEvent,
  UiPresentationProducer,
  UiSeatControlRequest,
} from "../generated";
import type { SeatAppendIdentityInput } from "./session";

export interface RyeOsKeyOutcome {
  readonly handled: boolean;
  readonly envelope: RyeOsEnvelope;
}

/** Exact callable surface generated by wasm-bindgen for the Rust UI core. */
export interface RyeOsWasmApi {
  default(input: { module_or_path: string | URL | Request | BufferSource }): Promise<unknown>;
  ryeos_start(session: unknown, presentationId: string, viewport: BrowserViewport, nowMs: bigint): RyeOsEnvelope;
  ryeos_dispatch(event: RyeOsEvent): RyeOsEnvelope;
  ryeos_apply_effect_result(result: RyeOsEffectResult): RyeOsEnvelope;
  ryeos_key(event: RyeOsKeyEvent): RyeOsKeyOutcome;
  ryeos_seat_events(): SeatEvent[];
  ryeos_seat_append_identity(identity: SeatAppendIdentityInput): string;
  ryeos_seat_control_identity(request: UiSeatControlRequest): string;
  ryeos_replay_acknowledged_seat_events(producer: UiPresentationProducer, captured: SeatEvent[], events: unknown[]): RyeOsEnvelope;
  ryeos_begin_seat_replay(session: unknown, presentationId: string, viewport: BrowserViewport, nowMs: bigint): void;
  ryeos_begin_seat_reproof(session: unknown, presentationId: string, viewport: BrowserViewport, nowMs: bigint): void;
  ryeos_stage_seat_replay_events(events: unknown[]): void;
  ryeos_stage_seat_transfer_proof(proof: unknown): void;
  ryeos_stage_seat_move_freeze_cancellation_proof(proof: unknown): void;
  ryeos_commit_seat_replay(completion: SeatHistoryCompletion): RyeOsEnvelope;
  ryeos_commit_seat_reproof(completion: SeatHistoryCompletion): RyeOsEnvelope;
  ryeos_acknowledged_seat_prefix_len(): bigint;
  ryeos_abort_seat_replay(): void;
  ryeos_require_presentation_producer_ready(producer: UiPresentationProducer, nextEngineSeq: bigint): void;
  ryeos_layout_preference_key(): string | undefined;
  ryeos_export_layout_preferences(): string;
  ryeos_restore_layout_preferences(encoded: string): RyeOsEnvelope;
  ryeos_export_active_view_set_template(id: string, name: string): string;
  ryeos_open_saved_view_set_template(encoded: string): RyeOsEnvelope;
}

export async function loadWasm(): Promise<RyeOsWasmApi> {
  const specifier = "/ui/assets/ryeos_web.js";
  const module: unknown = await import(/* @vite-ignore */ specifier);
  if (!isWasmApi(module)) throw new Error("installed RyeOS WASM module has an invalid export surface");
  return module;
}

function isWasmApi(value: unknown): value is RyeOsWasmApi {
  if (typeof value !== "object" || value === null) return false;
  const exports = value as Record<string, unknown>;
  return [
    "default", "ryeos_start", "ryeos_dispatch", "ryeos_apply_effect_result",
    "ryeos_key", "ryeos_seat_events", "ryeos_seat_append_identity", "ryeos_seat_control_identity",
    "ryeos_replay_acknowledged_seat_events", "ryeos_begin_seat_replay", "ryeos_stage_seat_replay_events", "ryeos_stage_seat_transfer_proof", "ryeos_stage_seat_move_freeze_cancellation_proof", "ryeos_commit_seat_replay", "ryeos_abort_seat_replay",
    "ryeos_require_presentation_producer_ready",
    "ryeos_begin_seat_reproof", "ryeos_commit_seat_reproof", "ryeos_acknowledged_seat_prefix_len",
    "ryeos_layout_preference_key", "ryeos_export_layout_preferences",
    "ryeos_restore_layout_preferences",
    "ryeos_export_active_view_set_template", "ryeos_open_saved_view_set_template",
  ].every((name) => typeof exports[name] === "function");
}

export type DispatchUi = (event: RyeOsUiEvent) => void;
